117	fn valid_id(id: &str) -> Result<(), String> {
118	    if !id.is_empty()
119	        && id.len() <= 40
120	        && id
121	            .bytes()
122	            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
123	    {
124	        Ok(())
125	    } else {
126	        Err("A change id is a-z, 0-9 and dashes".into())
127	    }
128	}
