{"type":"user","message":{"role":"user","content":[{"tool_use_id":"call-4248c5af-cca0-48dc-9a8d-18f1ba04ff2f-18","type":"tool_result","content":"160	function TodayBody({ projectId }: { projectId: string }) {
161	  useWaitingChatsVersion();
162	  useChatsBusyVersion();
163	  useMonoFailuresVersion();
164	  const { stuck: stuckWorkersNow } = useStuckWorkers();
165	  const delegationRows = useDelegationRows();
166	  const [sheet, setSheet] = useState<SheetFor | null>(null);
167	  const [query, setQuery] = useState("");
168	  const [shown, setShown] = useState(25);
169	  const data = hubData();
170	  const connection = data.connection();
171	  // The update card shows even when Today can't load (r28: otherwise it sits under the Since paragraph, never above it).
172	  // Loading and "no projects yet" are HubHome's (G1): a project's Today only ever draws for a real project.
173	  if (connection.status === "unreachable") return <><ShipNotice /><AshOsDown message={connection.message} retrying={connection.retrying} onRetry={() => data.retry()} /></>;
174	  const since = data.sinceSummary(projectId);
175	  const sinceAt = data.sinceAt();
176	  // C9: one paragraph of what happened since Ash was last active (typing): Ash OS's words about the project's work, then
177	  // the app's own real events (work handed out, finished and reported back, stuck: appSince.ts). A project's Today says
178	  // only what happened in that project.
179	  const sinceMs = sinceAt ? Date.parse(sinceAt) : NaN;
180	  const appSince = Number.isFinite(sinceMs)
181	    ? appSinceText({
182	        sinceMs,
183	        rows: delegationRows.filter((r) => r.project === projectId),
184	        stuck: stuckWorkersNow.filter((s) => stuckProject(s)?.id === projectId),
185	        changes: [],
186	        nameOf: (row) => leadNameOf({ row }),
