{"type":"user","message":{"role":"user","content":[{"tool_use_id":"call-4b0779ca-df2a-4d6a-bb1c-e9cbadc18e17-98","type":"tool_result","content":"1	import { useCallback, useReducer, useRef } from "react";
2	import { nextUnseenReplyCounts } from "../model/sessionDone";
3	
4	/**
5	 * Replies each tracked session finished while unfocused, plus any noted
6	 * from elsewhere (a habit's post), cleared once the session is focused.
7	 */
8	export function useUnseenReplyCounts(
9	  trackedIds: ReadonlySet<string>,
10	  busySessionIds: ReadonlySet<string>,
11	  activeSessionId?: string,
12	): {
13	  counts: ReadonlyMap<string, number>;
14	  noteReply: (sessionId: string) => void;
15	} {
16	  const [, rerender] = useReducer((tick: number) => tick + 1, 0);
17	  const busyRef = useRef(busySessionIds);
18	  const focusedRef = useRef(activeSessionId);
19	  const trackedRef = useRef(trackedIds);
20	  const countsRef = useRef<ReadonlyMap<string, number>>(new Map());
21	  if (
22	    busyRef.current !== busySessionIds ||
23	    focusedRef.current !== activeSessionId ||
24	    trackedRef.current !== trackedIds
25	  ) {
26	    countsRef.current = nextUnseenReplyCounts({
27	      previousBusyIds: busyRef.current,
28	      busyIds: busySessionIds,
29	      previousCounts: countsRef.current,
30	      focusedSessionId: activeSessionId,
31	      trackedIds,
32	    });
33	    busyRef.current = busySessionIds;
34	    focusedRef.current = activeSessionId;
35	    trackedRef.current = trackedIds;
36	  }
37	  const noteReply = useCallback((sessionId: string) => {
38	    if (sessionId === focusedRef.current || !trackedRef.current.has(sessionId))
39	      return;
40	    const next = new Map(countsRef.current);
41	    next.set(sessionId, (next.get(sessionId) ?? 0) + 1);
42	    countsRef.current = next;
43	    rerender();
44	  }, []);
