          if (!cancelled) setSearching(false);
        });
    }, 150);","numLines":80,"startLine":1,"totalLines":251}},"tool_result_meta":[{"id":"call-84fd73f0-4cbd-4a98-b9cb-e76dc3b164d5-118","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}

