180	export function jobTimeLabel(w: Worker, now = Date.now()): string {
181	  if (w.finishedAt) return w.finishedAt;
182	  // A paused job: since when it was paused, if Ash OS said; never the time it ran before (r28b).
183	  if (jobState(w) === "parked") return w.pausedSince ? `since ${w.pausedSince}` : "";
184	  if (w.stuck && w.stuckWorker) {
185	    const min = stuckMinutes(w.stuckWorker, now);
186	    return min < 1 ? "just now" : `for ${durationLabel(min)}`;
187	  }
188	  if (w.minutes < 1) return "just started";
189	  return `for ${durationLabel(w.minutes)}`;
190	}
