   WebKit's invalidation, so every focus move rechecks the whole page. With
   the whole group inside `:where()` WebKit keys the rule on `.group`. */
@custom-variant group-focus-within (&:where(.group:focus-within *));

@container settings (width < 560px) {
  .settings-row {
    flex-direction: column;
    gap: 0.75rem;
  }

  .settings-row-control {
    max-width: 100%;
    justify-content: flex-start;
  }

  .settings-row:has(> .settings-row-control > [role="switch"]:only-child) {
    flex-direction: row;
    gap: 1.5rem;
  }
}

@theme {
  /* Preserve descenders in compact labels, including two 10px lines in a 30px tab. */
  --leading-label: 1.4;
  --color-background-base: hsl(
    var(--theme-hue) var(--theme-saturation) var(--background-lightness)
  );
  --color-content: hsl(
    var(--theme-hue) var(--theme-saturation) var(--content-lightness)
  );
  /* Structural separators: use border-stroke, divide-stroke, or bg-stroke. */
  --color-stroke: color-mix(in srgb, var(--color-content) 7%, transparent);
  /* Interactive fills keep their dark-theme contrast but use gentler ink in
     light mode. Prefer these over content opacity for selected/raised UI. */
  --color-selection-subtle: color-mix(
    in srgb,
    var(--color-content) var(--selection-subtle-strength),
    transparent
  );
  --color-selection: color-mix(
    in srgb,
    var(--color-content) var(--selection-strength),
    transparent
  );
  --color-selection-strong: color-mix(
    in srgb,
    var(--color-content) var(--selection-strong-strength),
    transparent
  );
  --color-selection-hover: color-mix(
    in srgb,
    var(--color-content) var(--selection-hover-strength),
    transparent
  );
  --color-selection-emphasis: color-mix(
    in srgb,
    var(--color-content) var(--selection-emphasis-strength),
    transparent
  );
  --color-accent: hsl(211 92% 62%);
  /* Theme tokens for hub surfaces (Pages, Appearance schemes). A scheme only overrides the --theme-* and --scheme-*
     inputs, so every screen built on these restyles with no per-screen edits. Default: monochrome glass. */
  --color-surface: color-mix(in srgb, var(--color-content) var(--scheme-surface-strength, 4%), transparent);
  --color-surface-raised: color-mix(in srgb, var(--color-content) 8%, transparent);
  /* Inner padding of a hub card; bespoke pages get it too. */
  --space-card: 12px;
  --color-surface-ring: color-mix(in srgb, var(--color-content) 10%, transparent);
  --color-theme-accent: var(--scheme-accent, var(--color-content));
  /* Status only: the one place colour means something. */
  --color-status-ok: var(--scheme-status-ok, #34d399);
  --color-status-warn: var(--scheme-status-warn, #fbbf24);
  --color-status-bad: var(--scheme-status-bad, #f87171);
  --color-skill: #e8c547;
  --color-mention: #38bdf8;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --font-sans:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
    Ubuntu, Cantarell, "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  /* Diff colors. `diff-add`/`diff-del` are the solid marker hues, `-fg` is
     readable text on the theme background, `-bg`/`-gutter` are row tints.
     Palettes below swap them; diff UI must also show a +/- glyph so color is
     never the only cue. */
  --color-diff-add: #10b981;
  --color-diff-add-fg: #6ee7b7;
  --color-diff-add-bg: color-mix(
    in srgb,
    var(--color-diff-add) 15%,
    transparent
  );
  --color-diff-add-gutter: color-mix(
    in srgb,
    var(--color-diff-add) 25%,
    transparent
  );
  --color-diff-del: #f43f5e;
  --color-diff-del-fg: #fda4af;
  --color-diff-del-bg: color-mix(
    in srgb,
    var(--color-diff-del) 15%,
    transparent
  );
  --color-diff-del-gutter: color-mix(
    in srgb,
    var(--color-diff-del) 25%,
    transparent
  );
}

